insert into question_versions (env, question_id, v, status, text, options, correct, explanation, subject_id, topic_id, difficulty, source, source_url, last_verified, next_review, author_id, reviewer_id, review_note, change_note, created_at, approved_at, published_at) select env, question_id, v, status, text, options, correct, explanation, subject_id, topic_id, difficulty, source, source_url, last_verified, next_review, author_id, reviewer_id, review_note, change_note, created_at, approved_at, published_at from jsonb_populate_recordset(null::question_versions, $j$[{"env":"demo","question_id":"q01","v":1,"status":"published","text":"Se la legge o un regolamento non prevedono un termine diverso, entro quanti giorni deve concludersi un procedimento amministrativo?","options":["30 giorni","60 giorni","90 giorni","120 giorni"],"correct":0,"explanation":"L'art. 2 della L. 241/1990 fissa in 30 giorni il termine generale, salvo diversa previsione di legge o regolamento.","subject_id":"s-amm","topic_id":"t-proc","difficulty":1,"source":"L. 241/1990, art. 2","source_url":"https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1990-08-07;241","last_verified":"2026-09-17","next_review":"2027-09-17","author_id":"00000000-0000-4000-8000-0000000000e1","reviewer_id":"00000000-0000-4000-8000-0000000000a1","review_note":null,"change_note":"Prima versione","created_at":"2026-06-29T15:05:11.381Z","approved_at":"2026-07-01T15:05:11.381Z","published_at":"2026-07-01T15:05:11.381Z"},{"env":"demo","question_id":"q02","v":1,"status":"published","text":"Quale figura viene individuata per ogni procedimento ai sensi degli artt. 4-6 della L. 241/1990?","options":["Il difensore civico","Il responsabile del procedimento","Il segretario generale","L'organo di indirizzo politico"],"correct":1,"explanation":"Le amministrazioni individuano l'unità organizzativa e il responsabile del procedimento, che cura l'istruttoria.","subject_id":"s-amm","topic_id":"t-proc","difficulty":1,"source":"L. 241/1990, artt. 4-6","source_url":"https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1990-08-07;241","last_verified":"2026-09-16","next_review":"2027-09-16","author_id":"00000000-0000-4000-8000-0000000000e2","reviewer_id":"00000000-0000-4000-8000-0000000000a1","review_note":null,"change_note":"Prima versione","created_at":"2026-06-29T16:05:11.381Z","approved_at":"2026-07-01T16:05:11.381Z","published_at":"2026-07-01T16:05:11.381Z"},{"env":"demo","question_id":"q03","v":1,"status":"published","text":"Nei procedimenti a istanza di parte, prima di adottare un provvedimento negativo, l'amministrazione deve:","options":["Pubblicare l'atto all'albo pretorio","Chiedere un parere al TAR","Comunicare i motivi che ostano all'accoglimento della domanda","Sospendere il procedimento per 90 giorni"],"correct":2,"explanation":"È il preavviso di rigetto: l'interessato può presentare osservazioni entro 10 giorni.","subject_id":"s-amm","topic_id":"t-proc","difficulty":2,"source":"L. 241/1990, art. 10-bis","source_url":"https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1990-08-07;241","last_verified":"2026-09-15","next_review":"2027-09-15","author_id":"00000000-0000-4000-8000-0000000000e1","reviewer_id":"00000000-0000-4000-8000-0000000000a1","review_note":null,"change_note":"Prima versione","created_at":"2026-06-29T17:05:11.381Z","approved_at":"2026-07-01T17:05:11.381Z","published_at":"2026-07-01T17:05:11.381Z"},{"env":"demo","question_id":"q04","v":1,"status":"published","text":"Nei procedimenti a istanza di parte per cui opera il silenzio assenso, la mancata risposta nei termini equivale a:","options":["Rigetto della domanda","Accoglimento della domanda","Sospensione del procedimento","Archiviazione d'ufficio"],"correct":1,"explanation":"Salvo le eccezioni previste, il silenzio dell'amministrazione equivale a provvedimento di accoglimento.","subject_id":"s-amm","topic_id":"t-proc","difficulty":2,"source":"L. 241/1990, art. 20","source_url":"https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1990-08-07;241","last_verified":"2026-09-14","next_review":"2027-09-14","author_id":"00000000-0000-4000-8000-0000000000e2","reviewer_id":"00000000-0000-4000-8000-0000000000a1","review_note":null,"change_note":"Prima versione","created_at":"2026-06-29T18:05:11.381Z","approved_at":"2026-07-01T18:05:11.381Z","published_at":"2026-07-01T18:05:11.381Z"},{"env":"demo","question_id":"q05","v":1,"status":"published","text":"Un provvedimento adottato in violazione di legge è, di regola:","options":["Annullabile","Nullo","Inesistente","Pienamente valido"],"correct":0,"explanation":"La violazione di legge, insieme a eccesso di potere e incompetenza, è causa di annullabilità.","subject_id":"s-amm","topic_id":"t-atti","difficulty":1,"source":"L. 241/1990, art. 21-octies","source_url":"https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1990-08-07;241","last_verified":"2026-09-13","next_review":"2027-09-13","author_id":"00000000-0000-4000-8000-0000000000e1","reviewer_id":"00000000-0000-4000-8000-0000000000a1","review_note":null,"change_note":"Prima versione","created_at":"2026-06-29T19:05:11.381Z","approved_at":"2026-07-01T19:05:11.381Z","published_at":"2026-07-01T19:05:11.381Z"},{"env":"demo","question_id":"q06","v":1,"status":"published","text":"Per i provvedimenti di autorizzazione o di attribuzione di vantaggi economici, l'annullamento d'ufficio può intervenire entro un termine non superiore a:","options":["18 mesi","3 anni","12 mesi","6 mesi"],"correct":2,"explanation":"Il termine massimo è stato ridotto a dodici mesi dal D.L. 77/2021. Verificare sempre il testo vigente.","subject_id":"s-amm","topic_id":"t-atti","difficulty":3,"source":"L. 241/1990, art. 21-nonies","source_url":"https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1990-08-07;241","last_verified":"2025-10-12","next_review":"2026-10-12","author_id":"00000000-0000-4000-8000-0000000000e2","reviewer_id":"00000000-0000-4000-8000-0000000000a1","review_note":null,"change_note":"Prima versione","created_at":"2026-06-29T20:05:11.381Z","approved_at":"2026-07-01T20:05:11.381Z","published_at":"2026-07-01T20:05:11.381Z"},{"env":"demo","question_id":"q07","v":1,"status":"published","text":"La revoca di un provvedimento amministrativo può essere disposta:","options":["Solo per vizi di legittimità","Per sopravvenuti motivi di pubblico interesse","Esclusivamente dal giudice amministrativo","Solo su richiesta del destinatario"],"correct":1,"explanation":"La revoca opera per sopravvenuti motivi di pubblico interesse, mutamento della situazione di fatto o nuova valutazione dell'interesse pubblico originario.","subject_id":"s-amm","topic_id":"t-atti","difficulty":2,"source":"L. 241/1990, art. 21-quinquies","source_url":"https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1990-08-07;241","last_verified":"2026-09-11","next_review":"2027-09-11","author_id":"00000000-0000-4000-8000-0000000000e1","reviewer_id":"00000000-0000-4000-8000-0000000000a1","review_note":null,"change_note":"Prima versione","created_at":"2026-06-29T21:05:11.381Z","approved_at":"2026-07-01T21:05:11.381Z","published_at":"2026-07-01T21:05:11.381Z"},{"env":"demo","question_id":"q08","v":1,"status":"published","text":"L'accesso civico generalizzato è disciplinato da:","options":["L. 190/2012","D.Lgs. 165/2001","D.Lgs. 33/2013","D.P.R. 445/2000"],"correct":2,"explanation":"Il D.Lgs. 33/2013, modificato dal D.Lgs. 97/2016, consente a chiunque di accedere a dati e documenti ulteriori rispetto a quelli pubblicati.","subject_id":"s-amm","topic_id":"t-acc","difficulty":1,"source":"D.Lgs. 33/2013, art. 5","source_url":"https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2013-03-14;33","last_verified":"2026-09-10","next_review":"2027-09-10","author_id":"00000000-0000-4000-8000-0000000000e2","reviewer_id":"00000000-0000-4000-8000-0000000000a1","review_note":null,"change_note":"Prima versione","created_at":"2026-06-29T22:05:11.381Z","approved_at":"2026-07-01T22:05:11.381Z","published_at":"2026-07-01T22:05:11.381Z"},{"env":"demo","question_id":"q09","v":1,"status":"published","text":"Il diritto di accesso ai documenti amministrativi ai sensi della L. 241/1990 spetta a chi ha:","options":["Un interesse diretto, concreto e attuale","Qualsiasi curiosità, senza motivazione","La qualifica di dipendente pubblico","L'iscrizione a un albo professionale"],"correct":0,"explanation":"L'accesso documentale richiede un interesse diretto, concreto e attuale, collegato al documento richiesto.","subject_id":"s-amm","topic_id":"t-acc","difficulty":2,"source":"L. 241/1990, art. 22","source_url":"https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1990-08-07;241","last_verified":"2026-09-09","next_review":"2027-09-09","author_id":"00000000-0000-4000-8000-0000000000e1","reviewer_id":"00000000-0000-4000-8000-0000000000a1","review_note":null,"change_note":"Prima versione","created_at":"2026-06-29T23:05:11.381Z","approved_at":"2026-07-01T23:05:11.381Z","published_at":"2026-07-01T23:05:11.381Z"},{"env":"demo","question_id":"q10","v":1,"status":"published","text":"Decorsi inutilmente 30 giorni dalla richiesta di accesso ai documenti, la richiesta si intende:","options":["Accolta","Respinta","Sospesa","Trasferita al prefetto"],"correct":1,"explanation":"L'art. 25 prevede il silenzio rigetto: il richiedente può ricorrere al TAR o al difensore civico.","subject_id":"s-amm","topic_id":"t-acc","difficulty":2,"source":"L. 241/1990, art. 25","source_url":"https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1990-08-07;241","last_verified":"2026-09-08","next_review":"2027-09-08","author_id":"00000000-0000-4000-8000-0000000000e2","reviewer_id":"00000000-0000-4000-8000-0000000000a1","review_note":null,"change_note":"Prima versione","created_at":"2026-06-30T00:05:11.381Z","approved_at":"2026-07-02T00:05:11.381Z","published_at":"2026-07-02T00:05:11.381Z"},{"env":"demo","question_id":"q11","v":1,"status":"published","text":"Secondo l'art. 97 della Costituzione, i pubblici uffici sono organizzati in modo da assicurare:","options":["La massima redditività","Il buon andamento e l'imparzialità","La riservatezza degli atti","L'autonomia finanziaria"],"correct":1,"explanation":"L'art. 97 richiama il buon andamento e l'imparzialità dell'amministrazione.","subject_id":"s-cost","topic_id":"t-princ","difficulty":1,"source":"Costituzione, art. 97","source_url":"https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:costituzione","last_verified":"2026-09-07","next_review":"2027-09-07","author_id":"00000000-0000-4000-8000-0000000000e1","reviewer_id":"00000000-0000-4000-8000-0000000000a1","review_note":null,"change_note":"Prima versione","created_at":"2026-06-30T01:05:11.381Z","approved_at":"2026-07-02T01:05:11.381Z","published_at":"2026-07-02T01:05:11.381Z"},{"env":"demo","question_id":"q12","v":1,"status":"published","text":"Agli impieghi nelle pubbliche amministrazioni si accede, salvo i casi stabiliti dalla legge, mediante:","options":["Chiamata diretta","Concorso","Sorteggio pubblico","Nomina dell'organo politico"],"correct":1,"explanation":"L'art. 97, ultimo comma, stabilisce la regola del concorso.","subject_id":"s-cost","topic_id":"t-princ","difficulty":1,"source":"Costituzione, art. 97","source_url":"https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:costituzione","last_verified":"2026-09-06","next_review":"2027-09-06","author_id":"00000000-0000-4000-8000-0000000000e2","reviewer_id":"00000000-0000-4000-8000-0000000000a1","review_note":null,"change_note":"Prima versione","created_at":"2026-06-30T02:05:11.381Z","approved_at":"2026-07-02T02:05:11.381Z","published_at":"2026-07-02T02:05:11.381Z"},{"env":"demo","question_id":"q12","v":2,"status":"review","text":"Agli impieghi nelle pubbliche amministrazioni si accede, salvo i casi stabiliti dalla legge, mediante:","options":["Chiamata diretta","Concorso","Sorteggio pubblico","Nomina dell'organo politico"],"correct":1,"explanation":"L'art. 97, quarto comma, stabilisce che agli impi