insert into materials (id, env, title, subject_id, topic_id, format, status, minutes, source, key_concepts, last_verified, next_review, author_id) select id, env, title, subject_id, topic_id, format, status, minutes, source, key_concepts, last_verified, next_review, author_id from jsonb_populate_recordset(null::materials, $j$[{"id":"m01","env":"demo","title":"La legge 241/1990 in sintesi","subject_id":"s-amm","topic_id":"t-proc","format":"scheda","status":"published","minutes":12,"source":"L. 241/1990","key_concepts":["Termine generale: 30 giorni","Responsabile del procedimento","Preavviso di rigetto (art. 10-bis)","Silenzio assenso (art. 20)"],"last_verified":"2026-09-27","next_review":"2027-09-22","author_id":"00000000-0000-4000-8000-0000000000e1"},{"id":"m02","env":"demo","title":"Accesso documentale e accesso civico","subject_id":"s-amm","topic_id":"t-acc","format":"scheda","status":"published","minutes":9,"source":"L. 241/1990; D.Lgs. 33/2013","key_concepts":["Interesse diretto, concreto e attuale","Accesso civico semplice","Accesso civico generalizzato","Silenzio rigetto dopo 30 giorni"],"last_verified":"2026-09-26","next_review":"2027-09-21","author_id":"00000000-0000-4000-8000-0000000000e1"},{"id":"m03","env":"demo","title":"Gli organi del comune","subject_id":"s-eell","topic_id":"t-organi","format":"scheda","status":"published","minutes":10,"source":"D.Lgs. 267/2000","key_concepts":["Consiglio, giunta e sindaco","Mandato di cinque anni","La giunta è nominata dal sindaco"],"last_verified":"2026-09-25","next_review":"2027-09-20","author_id":"00000000-0000-4000-8000-0000000000e1"},{"id":"m04","env":"demo","title":"Principi fondamentali della Costituzione","subject_id":"s-cost","topic_id":"t-princ","format":"scheda","status":"published","minutes":8,"source":"Costituzione, artt. 1-12 e 97","key_concepts":["Uguaglianza formale e sostanziale","Buon andamento e imparzialità","Accesso agli impieghi mediante concorso"],"last_verified":"2026-09-24","next_review":"2027-09-19","author_id":"00000000-0000-4000-8000-0000000000e1"},{"id":"m05","env":"demo","title":"Il ciclo del bilancio negli enti locali","subject_id":"s-cont","topic_id":"t-bil","format":"scheda","status":"published","minutes":11,"source":"D.Lgs. 267/2000; D.Lgs. 118/2011","key_concepts":["DUP entro il 31 luglio","Bilancio entro il 31 dicembre","PEG deliberato dalla giunta","Rendiconto entro il 30 aprile"],"last_verified":"2026-09-23","next_review":"2027-09-18","author_id":"00000000-0000-4000-8000-0000000000e1"},{"id":"m06","env":"demo","title":"Schema riassuntivo TUEL","subject_id":"s-eell","topic_id":"t-funz","format":"pdf-download","status":"draft","minutes":5,"source":"D.Lgs. 267/2000","key_concepts":[],"last_verified":"2026-09-22","next_review":"2027-09-17","author_id":"00000000-0000-4000-8000-0000000000e1"},{"id":"m07","env":"demo","title":"Codice di comportamento: guida alla lettura","subject_id":"s-pi","topic_id":"t-comp","format":"pdf-view","status":"draft","minutes":15,"source":"D.P.R. 62/2013","key_concepts":[],"last_verified":"2026-09-21","next_review":"2027-09-16","author_id":"00000000-0000-4000-8000-0000000000e1"},{"id":"m08","env":"demo","title":"La conferenza di servizi","subject_id":"s-amm","topic_id":"t-proc","format":"scheda","status":"draft","minutes":7,"source":"L. 241/1990, artt. 14 e ss.","key_concepts":[],"last_verified":"2026-09-20","next_review":"2027-09-15","author_id":"00000000-0000-4000-8000-0000000000e1"}]$j$::jsonb) on conflict do nothing;
insert into material_sections (env, material_id, id, position, title, body) select env, material_id, id, position, title, body from jsonb_populate_recordset(null::material_sections, $j$[{"env":"demo","material_id":"m01","id":"m01-s1","position":1,"title":"Principi generali","body":"L'attività amministrativa persegue i fini determinati dalla legge ed è retta da criteri di economicità, efficacia, imparzialità, pubblicità e trasparenza (art. 1). L'amministrazione non può aggravare il procedimento se non per straordinarie e motivate esigenze."},{"env":"demo","material_id":"m01","id":"m01-s2","position":2,"title":"Termini del procedimento","body":"Il procedimento si conclude con un provvedimento espresso. In assenza di un termine diverso la durata è di 30 giorni (art. 2). Termini più lunghi, fino a 90 o, in casi particolari, 180 giorni, possono essere stabiliti nei casi previsti."},{"env":"demo","material_id":"m01","id":"m01-s3","position":3,"title":"Responsabile del procedimento","body":"Per ogni procedimento è individuato un responsabile (artt. 4-6), che valuta i presupposti, cura l'istruttoria, può chiedere la rettifica di dichiarazioni e propone o adotta il provvedimento finale."},{"env":"demo","material_id":"m01","id":"m01-s4","position":4,"title":"Partecipazione","body":"L'avvio del procedimento è comunicato ai soggetti interessati (art. 7). Nei procedimenti a istanza di parte, prima di un diniego, l'amministrazione comunica i motivi ostativi (art. 10-bis) e l'interessato può presentare osservazioni entro 10 giorni."},{"env":"demo","material_id":"m01","id":"m01-s5","position":5,"title":"Silenzio della PA","body":"Nei casi previsti dall'art. 20 il silenzio equivale ad accoglimento. Negli altri casi l'inerzia può essere contestata davanti al giudice amministrativo."},{"env":"demo","material_id":"m02","id":"m02-s1","position":1,"title":"Accesso documentale","body":"Disciplinato dagli artt. 22 e seguenti della L. 241/1990, spetta a chi ha un interesse diretto, concreto e attuale corrispondente a una situazione giuridicamente tutelata."},{"env":"demo","material_id":"m02","id":"m02-s2","position":2,"title":"Accesso civico semplice","body":"Previsto dal D.Lgs. 33/2013, consente a chiunque di richiedere documenti e dati che l'amministrazione aveva l'obbligo di pubblicare e non ha pubblicato."},{"env":"demo","material_id":"m02","id":"m02-s3","position":3,"title":"Accesso civico generalizzato","body":"Consente a chiunque, senza motivazione, di accedere a dati e documenti ulteriori rispetto a quelli soggetti a pubblicazione, nel rispetto dei limiti a tutela di interessi pubblici e privati."},{"env":"demo","material_id":"m02","id":"m02-s4","position":4,"title":"Limiti e silenzio","body":"Decorsi 30 giorni dalla richiesta di accesso documentale senza risposta, la richiesta si intende respinta (art. 25)."},{"env":"demo","material_id":"m03","id":"m03-s1","position":1,"title":"Consiglio comunale","body":"È l'organo di indirizzo e di controllo politico-amministrativo. Delibera lo statuto, i regolamenti, i bilanci e gli atti fondamentali indicati dall'art. 42 del TUEL."},{"env":"demo","material_id":"m03","id":"m03-s2","position":2,"title":"Giunta","body":"Collabora con il sindaco nel governo del comune e compie gli atti che non sono riservati dalla legge al consiglio. I componenti sono nominati dal sindaco (art. 46)."},{"env":"demo","material_id":"m03","id":"m03-s3","position":3,"title":"Sindaco","body":"È l'organo responsabile dell'amministrazione del comune, rappresenta l'ente e sovrintende al funzionamento dei servizi e degli uffici. Dura in carica cinque anni."},{"env":"demo","material_id":"m03","id":"m03-s4","position":4,"title":"Segretario comunale","body":"Svolge compiti di collaborazione e funzioni di assistenza giuridico-amministrativa nei confronti degli organi dell'ente."},{"env":"demo","material_id":"m04","id":"m04-s1","position":1,"title":"Gli articoli 1-12","body":"I primi dodici articoli definiscono i caratteri della Repubblica: democratica e fondata sul lavoro, garante dei diritti inviolabili, una e indivisibile, aperta all'ordinamento internazionale."},{"env":"demo","material_id":"m04","id":"m04-s2","position":2,"title":"Uguaglianza","body":"L'art. 3 afferma l'uguaglianza davanti alla legge (formale) e impegna la Repubblica a rimuovere gli ostacoli economici e sociali che la limitano (sostanziale)."},{"env":"demo","material_id":"m04","id":"m04-s3","position":3,"title":"L'amministrazione nella Costituzione","body":"L'art. 97 richiede che i pubblici uffici siano organizzati secondo il buon andamento e l'imparzialità e che agli impieghi si acceda mediante concorso, salvo i casi stabiliti dalla legge."},{"env":"demo","material_id":"m05","id":"m05-s1","position":1,"title":"Programmazione: il DUP","body":"Il Documento unico di programmazione guida strategicamente e operativamente l'ente ed è presentato dalla giunta al consiglio entro il 31 luglio."},{"env":"demo","material_id":"m05","id":"m05-s2","position":2,"title":"Bilancio di previsione","body":"Il bilancio di previsione finanziario è deliberato entro il 31 dicembre e riguarda almeno un triennio."},{"env":"demo","material_id":"m05","id":"m05-s3","position":3,"title":"PEG","body":"Il piano esecutivo di gestione, deliberato dalla giunta, affida obiettivi e risorse ai responsabili dei servizi."},{"env":"demo","material_id":"m05","id":"m05-s4","position":4,"title":"Rendiconto","body":"Il rendiconto della gestione è deliberato dal consiglio entro il 30 aprile dell'anno successivo."},{"env":"demo","material_id":"m08","id":"m08-s1","position":1,"title":"Bozza","body":"Contenuto in preparazione."}]$j$::jsonb) on conflict do nothing;
